import{_ as o}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as r,af as d}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Grok Build 术语表与设计解读","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/grok/grok-glossary.md","filePath":"zh/products/ai-coding/grok/grok-glossary.md","lastUpdated":1787110548000}'),a={name:"zh/products/ai-coding/grok/grok-glossary.md"};function l(c,t,n,i,s,g){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="grok-build-术语表与设计解读" tabindex="-1">Grok Build 术语表与设计解读 <a class="header-anchor" href="#grok-build-术语表与设计解读" aria-label="Permalink to &quot;Grok Build 术语表与设计解读&quot;">​</a></h1><p>不教操作，只解释&quot;为什么长这样&quot;。理解了这些，速查表里那些看着零散的键和 flag 就会各归其位。</p><h2 id="都叫-grok-的东西" tabindex="-1">都叫 Grok 的东西 <a class="header-anchor" href="#都叫-grok-的东西" aria-label="Permalink to &quot;都叫 Grok 的东西&quot;">​</a></h2><p>第一次接触 xAI 的东西，最容易在名字上翻车。</p><table tabindex="0"><thead><tr><th>名字</th><th>是什么</th><th>在哪用</th></tr></thead><tbody><tr><td><a href="./grok-chat.html">Grok（聊天）</a></td><td>面向消费者的通用助手</td><td>grok.com、Grok App、X</td></tr><tr><td><a href="./grok-imagine.html">Imagine</a></td><td>生图 / 生视频 / 编辑</td><td><a href="https://grok.com/imagine" target="_blank" rel="noreferrer">grok.com/imagine</a>；程序入口是 <a href="https://docs.x.ai/developers/model-capabilities/imagine" target="_blank" rel="noreferrer">Imagine API</a></td></tr><tr><td><a href="./grok-voice.html">Voice</a></td><td>两箱：<strong>产品</strong> Voice（grok.com / App 免提说话）和 <strong>Voice API</strong>（TTS / STT / Speech to Speech）</td><td>grok.com；<code>api.x.ai</code></td></tr><tr><td><a href="./grok-connectors.html">Connectors</a></td><td>聊天里连邮箱、文件、日历、目录 OAuth 或公网 MCP。不是 Grok Build 的 <code>grok mcp add</code></td><td><a href="https://grok.com/connectors" target="_blank" rel="noreferrer">grok.com/connectors</a></td></tr><tr><td>Build Mode</td><td>grok.com / Grok App 的<strong>聊天模式</strong>（模式切换选 <strong>Build</strong>）。Early Beta 仅 SuperGrok Heavy，Web / iOS / Android（<a href="https://x.ai/grok/build-mode" target="_blank" rel="noreferrer">x.ai/grok/build-mode</a>、<a href="https://x.ai/news/grok-build-mode" target="_blank" rel="noreferrer">news</a>）。官方原文：&quot;Tell Grok an idea, and it builds a working version live in your chat.&quot; 发布到 grok.me 或自定义域名。网站 / 应用 / 游戏 / 看板（看板可用 Connectors）。不用安装。<strong>不是</strong> Grok Build。官方密度仍是营销页 + 一篇 news，不单独开教程</td><td>grok.com</td></tr><tr><td>grok.me</td><td>Build Mode 的<strong>发布域名</strong>（官方原文：&quot;Publish to a grok.me link or a custom domain you own&quot;）。不是独立产品，也不是 CLI</td><td><code>*.grok.me</code></td></tr><tr><td><strong>Grok Build</strong></td><td>编码 agent，命令行工具，二进制名 <code>grok</code>。文档在 <code>docs.x.ai/build/*</code></td><td>你的终端</td></tr><tr><td><a href="./grok-bot.html">Grok Bot</a></td><td>跑在一台持久云电脑上的具名同事。桌面 + iOS。文档：<a href="https://docs.x.ai/grok-bot/overview" target="_blank" rel="noreferrer">docs.x.ai/grok-bot</a>。<strong>不是</strong> Grok Build 的 headless</td><td><a href="https://x.ai/bot" target="_blank" rel="noreferrer">x.ai/bot</a></td></tr><tr><td><a href="./grok-business.html">Grok Business</a></td><td>团队工作区、SuperGrok / SuperGrok Heavy 许可证、组织分享。文档：<a href="https://docs.x.ai/grok/user-guide" target="_blank" rel="noreferrer">docs.x.ai/grok/user-guide</a></td><td>console.x.ai + grok.com</td></tr><tr><td><code>grok-4.6</code></td><td>通用旗舰模型，也是 Grok Build 的默认驱动</td><td>Grok Build 和 xAI API 都能用</td></tr><tr><td><code>grok-build-0.1</code></td><td>专为编码 agent 场景训练的模型</td><td>同上</td></tr><tr><td>xAI API</td><td><code>https://api.x.ai/v1</code>，模型的 HTTP 接口</td><td>你自己的程序</td></tr></tbody></table><p>本站这套文档的主线是 <strong>Grok Build</strong>。官方文档站其实不止两棵树：<code>docs.x.ai/build/*</code> 讲 CLI，<code>docs.x.ai/developers/*</code> 讲 API，<code>docs.x.ai/grok/*</code> 讲 grok.com 消费端，<code>docs.x.ai/grok-bot/*</code> 讲 Grok Bot。两边的术语和配置互不通用。</p><p><strong>不是官方产品名或产品规格（正文不要当事实写）：</strong></p><ul><li>&quot;Grok Code&quot;、&quot;Grok CLI&quot; —— 官方产品名是 Grok Build，可执行文件是 <code>grok</code>，仓库是 <a href="https://github.com/xai-org/grok-build" target="_blank" rel="noreferrer">xai-org/grok-build</a>。</li><li>官方 VS Code / JetBrains 插件 —— 编辑器集成走 ACP（<code>grok agent stdio</code>）。</li><li>把 grok.me 当成独立 &quot;Build 产品&quot; —— 它只是 Build Mode 的发布 URL。</li><li>三方博客里的「Grok 4.3」「200 万 token 上下文」「Arena Mode」「8 路并行」当作产品规格 —— 本套文档只记录 <a href="https://docs.x.ai/developers/models" target="_blank" rel="noreferrer">docs.x.ai</a> 或 <a href="https://x.ai" target="_blank" rel="noreferrer">x.ai</a> 原文里出现的 slug 和限额。</li></ul><p>选哪个产品面，看 <a href="./">学习地图</a> 的决策树。产品地图：<a href="./grok-chat.html">聊天</a>、<a href="./grok-imagine.html">Imagine</a>、<a href="./grok-voice.html">Voice</a>、<a href="./grok-connectors.html">Connectors</a>、<a href="./grok-bot.html">Grok Bot</a>、<a href="./grok-business.html">Business</a>。</p><h2 id="一个-agent-三张脸" tabindex="-1">一个 agent，三张脸 <a class="header-anchor" href="#一个-agent-三张脸" aria-label="Permalink to &quot;一个 agent，三张脸&quot;">​</a></h2><p>官方对自己的定义是一句话：</p><blockquote><p>Grok Build is a powerful and extensible coding agent. Use it via an interactive TUI, headlessly in scripts or bots, or through the Agent Client Protocol (ACP) in other apps.</p></blockquote><p>三种&quot;面&quot;不是三个产品，是同一个 agent 的三个入口：</p><table tabindex="0"><thead><tr><th>面</th><th>入口</th><th>典型用途</th></tr></thead><tbody><tr><td>TUI</td><td><code>grok</code></td><td>人在终端里交互</td></tr><tr><td>Headless</td><td><code>grok -p &quot;...&quot;</code></td><td>CI、脚本、机器人</td></tr><tr><td>ACP</td><td><code>grok agent stdio</code></td><td>嵌进编辑器或自建编排器</td></tr></tbody></table><p>理解这点有实际收益：会话持久化、权限规则、hook、MCP、skill 在三种面下<strong>行为一致</strong>。你在 TUI 里调好的权限规则，headless 跑 CI 时照样生效；TUI 里开的会话，可以用 <code>grok --resume &lt;id&gt;</code> 在脚本里接着跑。所以这些能力只需要学一遍。</p><h2 id="权限和沙箱是两个正交的轴" tabindex="-1">权限和沙箱是两个正交的轴 <a class="header-anchor" href="#权限和沙箱是两个正交的轴" aria-label="Permalink to &quot;权限和沙箱是两个正交的轴&quot;">​</a></h2><p>这是 Grok Build 最容易被误解的设计。官方那句区分值得逐字记住：</p><blockquote><p>Permissions decide which tool calls may run. The sandbox is separate: it limits what an approved call can do on the filesystem and network.</p></blockquote><p>两个轴的分工：</p><ul><li><strong>权限</strong>回答&quot;这次调用要不要问我&quot;。它在<strong>调用发起前</strong>起作用，产物是允许 / 拒绝 / 询问。</li><li><strong>沙箱</strong>回答&quot;批准之后它最多能干到哪&quot;。它是<strong>操作系统级别</strong>的强制（Linux Landlock、macOS Seatbelt），不依赖模型或 agent 的自觉。</li></ul><p>为什么必须分开？因为二者的失效模式不同。权限是策略层，可以被&quot;我点了 always allow&quot;绕过；沙箱是执行层，即使 agent 完全失控、即使你开了 always-approve，它写不出 profile 允许的范围。真正需要安全兜底的场景（跑不可信仓库、审查陌生 PR）应该开沙箱，而不是指望自己每次都认真看权限提示。</p><p>反过来也成立：沙箱不是权限的替代品。<code>read-only</code> 能拦住写文件，但拦不住一次昂贵的、你并不想跑的只读操作。</p><p>顺着这个思路就能理解一个细节：always-approve 模式下，<code>deny</code> 规则和 <code>PreToolUse</code> hook <strong>仍然生效</strong>。因为 always-approve 只是把&quot;询问&quot;变成&quot;自动批准&quot;，并没有拆掉策略层本身。</p><h2 id="五层配置-为什么最高优先级在-etc" tabindex="-1">五层配置：为什么最高优先级在 <code>/etc</code> <a class="header-anchor" href="#五层配置-为什么最高优先级在-etc" aria-label="Permalink to &quot;五层配置：为什么最高优先级在 `/etc`&quot;">​</a></h2><p>配置的合并顺序是从低到高五层：</p><table tabindex="0"><thead><tr><th>优先级</th><th>来源</th><th>用途</th></tr></thead><tbody><tr><td>1（最低）</td><td><code>/etc/grok/managed_config.toml</code></td><td>系统级托管配置</td></tr><tr><td>2</td><td><code>~/.grok/managed_config.toml</code></td><td>用户级托管配置</td></tr><tr><td>3</td><td><code>~/.grok/config.toml</code></td><td>用户偏好</td></tr><tr><td>4</td><td><code>~/.grok/requirements.toml</code></td><td>用户级钉死设置</td></tr><tr><td>5（最高）</td><td><code>/etc/grok/requirements.toml</code></td><td>系统级钉死设置</td></tr></tbody></table><p>注意这个顺序有点反直觉的地方：<code>managed_config.toml</code> 在<strong>最低</strong>两层，<code>requirements.toml</code> 在<strong>最高</strong>两层。同一个 <code>/etc/grok/</code> 目录下的两个文件，一个垫底一个封顶。</p><p>拆开看就合理了，两类文件的语义完全不同：</p><ul><li><code>managed_config.toml</code> 是<strong>默认值分发</strong>——公司帮你预设好，但你想改就能改。所以它必须在用户配置下面。</li><li><code>requirements.toml</code> 是<strong>策略钉死</strong>（官方叫 fail-closed pin）——它的值不能被用户 <code>config.toml</code>、环境变量、远端设置或任何更低层覆盖。所以它必须在最上面。</li></ul><p>于是 <code>/etc/grok/requirements.toml</code> 成了合规策略的唯一权威来源，也是 MDM 推送的落点。同理可以解释另一条看似奇怪的规定：<code>[ui] disable_bypass_permissions_mode</code> 只在 <strong>root 拥有的来源</strong>里生效。如果用户自己写在 <code>~/.grok/requirements.toml</code> 里也算，那&quot;锁掉 always-approve&quot;这个策略就等于没锁——用户能加就能删。防篡改必须靠文件所有权，不能靠配置层级。</p><p>项目级 <code>.grok/config.toml</code> 的限制也出自同一逻辑：它只贡献 <code>[mcp_servers]</code>、<code>[plugins]</code>、<code>[permission]</code>。因为项目配置来自你 clone 的仓库，<strong>是别人写的</strong>。让一个仓库改你的模型、主题、沙箱默认值太危险；但共享 MCP 配置和权限规则是团队协作的合理需求，所以这三段开了口子。</p><h2 id="认证-四条路和一个解析顺序" tabindex="-1">认证：四条路和一个解析顺序 <a class="header-anchor" href="#认证-四条路和一个解析顺序" aria-label="Permalink to &quot;认证：四条路和一个解析顺序&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>触发</th><th>可刷新</th><th>适合</th></tr></thead><tbody><tr><td>浏览器 OIDC</td><td><code>grok login</code>（默认）</td><td>是</td><td>有浏览器的交互终端</td></tr><tr><td>设备码</td><td><code>grok login --device-auth</code></td><td>是</td><td>SSH、容器、无头主机</td></tr><tr><td>外部 auth provider</td><td>配置里 <code>auth_provider_command</code></td><td>是</td><td>企业 IdP、自建 token broker</td></tr><tr><td>API key</td><td><code>XAI_API_KEY</code> 或配置里 <code>model.api_key</code></td><td>否</td><td>脚本、CI/CD、无头自动化</td></tr></tbody></table><p>多种凭证同时存在时，Grok <strong>按模型</strong>逐个解析，顺序是：<code>model.api_key</code> &gt; <code>model.env_key</code> &gt; 当前会话 token &gt; <code>XAI_API_KEY</code>。</p><p>这个顺序解释了一个实际现象：你明明 <code>grok login</code> 登录过了，某个自定义模型却还在用 API key——因为 <code>[model.&lt;id&gt;]</code> 里配的 key 优先级高于会话 token。BYOK 模型和官方模型可以在同一个会话里走不同凭证，这是设计如此。</p><p>配置里请用 <code>env_key</code> 而不是 <code>api_key</code>，把密钥留在环境变量里，别落进会被 commit 的文件。</p><h2 id="agents-md-为什么越深的文件越优先" tabindex="-1">AGENTS.md：为什么越深的文件越优先 <a class="header-anchor" href="#agents-md-为什么越深的文件越优先" aria-label="Permalink to &quot;AGENTS.md：为什么越深的文件越优先&quot;">​</a></h2><p>项目规则的加载顺序是：先 <code>~/.grok/</code> 的全局规则，然后从仓库根一路向下读到当前工作目录，<strong>冲突时更深的文件胜出</strong>。</p><p>这个&quot;深者优先&quot;是为 monorepo 设计的。仓库根的 <code>AGENTS.md</code> 写全局约定，<code>packages/frontend/AGENTS.md</code> 写&quot;用 React，优先 CSS modules&quot;，<code>packages/backend/AGENTS.md</code> 写&quot;用 Express，遵循 REST&quot;。你在哪个包里工作，就自动拿到那个包的约定，不需要在 prompt 里重复说。</p><p>两个连带的设计：</p><ul><li><code>.gitignore</code> 命中的规则文件会被跳过。所以 <code>CLAUDE.local.md</code> 这种个人覆盖不会污染团队共享上下文——它本来就该被 ignore。</li><li>规则文件<strong>全量加载，没有大小上限</strong>。听起来很爽，但官方紧接着提醒：&quot;短而具体的指令比长的更容易被遵守。&quot; 规则文件不是文档，是给模型的约束，写长了等于没写。</li></ul><h2 id="plan-模式门的是编辑-不是-shell" tabindex="-1">Plan 模式门的是编辑，不是 shell <a class="header-anchor" href="#plan-模式门的是编辑-不是-shell" aria-label="Permalink to &quot;Plan 模式门的是编辑，不是 shell&quot;">​</a></h2><p>计划模式下只有会话计划文件能被编辑，其他编辑工具会被拒绝——<strong>即使在 auto 或 always-approve 下也一样</strong>。</p><p>但有一条必须知道的边界：</p><blockquote><p>Plan mode gates edit tools, not the shell — bash can still write via redirection.</p></blockquote><p>也就是说 plan 模式挡的是 <code>write</code> / <code>edit</code> 这类工具，不挡 bash。模型完全可以用 <code>echo ... &gt; file</code> 绕过去。所以 plan 模式的定位是<strong>协作机制</strong>（让你在动手前先看到方案），不是<strong>安全机制</strong>。要真正防写，用沙箱。</p><p>同理，subagent 不受父会话 plan 模式的编辑门限制（但会继承权限模式）。</p><h2 id="会话是可分支的状态-不是一条聊天记录" tabindex="-1">会话是可分支的状态，不是一条聊天记录 <a class="header-anchor" href="#会话是可分支的状态-不是一条聊天记录" aria-label="Permalink to &quot;会话是可分支的状态，不是一条聊天记录&quot;">​</a></h2><p>Grok Build 的会话默认全量落盘在 <code>~/.grok/sessions/</code>，按工作目录索引，prompt、响应、工具调用、文件快照都在里面。理解成&quot;带快照的状态机&quot;比理解成&quot;聊天记录&quot;更准确，因为它支持的操作是状态操作：</p><table tabindex="0"><thead><tr><th>操作</th><th>语义</th></tr></thead><tbody><tr><td><code>--resume</code> / <code>-c</code></td><td>加载状态继续</td></tr><tr><td><code>/fork</code></td><td>从当前状态分叉出一个对等 agent</td></tr><tr><td><code>/rewind</code></td><td>把状态<strong>连同磁盘文件</strong>回退到某个 turn</td></tr><tr><td><code>/compact</code></td><td>压缩历史，腾出上下文预算</td></tr></tbody></table><p><code>/rewind</code> 会改磁盘文件这件事必须单独强调一遍：它不是&quot;撤销对话&quot;，是&quot;撤销这段时间发生的一切&quot;，没提交 git 的改动会没。</p><p><code>--fork-session</code> 和 <code>/fork</code> 存在的理由是&quot;探索性分叉&quot;：同一个上下文起点，试两种方案互不干扰。配合 worktree（<code>grok -w</code>）就变成文件层面也隔离的并行开发——多个 agent 同时改同一个仓库而不互相覆盖。</p><p>worktree 不会自动清理，这也是有意的：agent 跑出来的东西你可能还没看过就删了太危险，所以 <code>gc</code> 只在手动调用时才跑。代价是你得自己记得 <code>grok worktree gc</code>。</p><h2 id="五种扩展机制的分工" tabindex="-1">五种扩展机制的分工 <a class="header-anchor" href="#五种扩展机制的分工" aria-label="Permalink to &quot;五种扩展机制的分工&quot;">​</a></h2><p>这五个概念最容易糊成一团，因为它们都能&quot;给 agent 加东西&quot;。区别在于加的是什么：</p><table tabindex="0"><thead><tr><th>机制</th><th>加的是</th><th>边界</th></tr></thead><tbody><tr><td><strong>Skill</strong></td><td>知识和流程（markdown + 脚本 + 资源）</td><td>不改变可用工具集</td></tr><tr><td><strong>MCP server</strong></td><td>工具（外部系统的能力）</td><td>通过协议接入，工具名带 <code>&lt;server&gt;__</code> 前缀</td></tr><tr><td><strong>Plugin</strong></td><td>打包分发的组合（skills + agents + hooks + MCP + LSP）</td><td>是容器，不是新能力类型</td></tr><tr><td><strong>Subagent</strong></td><td>独立上下文的执行单元</td><td>结束时把摘要交回父会话</td></tr><tr><td><strong>Workflow</strong></td><td>编排（扇出、验证、汇总一组 subagent）</td><td><code>.rhai</code> 脚本，跑在后台</td></tr><tr><td><strong>Persona</strong></td><td>行为叠加层（语气、关注点、契约）</td><td><strong>只改行为，不改能力</strong></td></tr></tbody></table><p>两个高频误解值得点名：</p><ol><li><strong><code>allowed-tools</code> 不是权限控制</strong>。它在 <code>SKILL.md</code> frontmatter 里，名字听着像白名单，但官方明确说它既不授予也不限制工具。想控制工具，用 <code>[permission]</code> 规则或 <code>--tools</code> / <code>--disallowed-tools</code>。</li><li><strong>Persona 不是 subagent 类型</strong>。换 persona 只换说话方式和关注点，不换它能调什么工具。</li></ol><p>Subagent 存在的根本理由是<strong>上下文经济</strong>：探索一个大仓库会产生大量中间输出，这些东西留在主会话里就是纯浪费。所以 <code>explore</code> 类型只读、无 shell、不改文件，它的职责是把一堆搜索结果压成一段结论交回来。同理 <code>plan</code> 类型也不动文件。</p><h2 id="为什么它主动兼容-claude-code" tabindex="-1">为什么它主动兼容 Claude Code <a class="header-anchor" href="#为什么它主动兼容-claude-code" aria-label="Permalink to &quot;为什么它主动兼容 Claude Code&quot;">​</a></h2><p>Grok Build 明确承诺零配置兼容 Claude Code：自动读 Claude 的 marketplace、plugin、skill、MCP、agent、hook 和指令文件，CLI flag 也保留 Claude 的别名。</p><p>这是一个迁移成本策略：AI 编码工具的切换成本主要不在&quot;学新命令&quot;，而在&quot;重建那一整套配置&quot;——你攒了半年的 skill、调好的 MCP、写熟的 <code>CLAUDE.md</code>。把这些东西直接读进来，切换成本就从&quot;重建&quot;降到&quot;跑一次试试&quot;。</p><p>但兼容有一条<strong>故意的例外</strong>：Claude 的 <code>managed-settings.json</code> 里 <code>disableBypassPermissionsMode: &quot;disable&quot;</code> 不会作用到 Grok 的 always-approve。官方给的理由是不让 Grok 继承宿主机的 Claude Code 封锁策略。这个例外本身很能说明兼容层的定位——它兼容的是<strong>你的资产</strong>，不是<strong>别人对你的限制</strong>。要在 Grok 侧锁，就在 Grok 自己的 <code>requirements.toml</code> 里写。</p><h2 id="为什么这份文档一定会过期" tabindex="-1">为什么这份文档一定会过期 <a class="header-anchor" href="#为什么这份文档一定会过期" aria-label="Permalink to &quot;为什么这份文档一定会过期&quot;">​</a></h2><p>Grok Build 目前是 early beta，2026 年 5 月 25 日发布。npm <code>@xai-official/grok</code> 的 <code>latest</code> 在 2026-08-12 到 2026-08-16 之间从 1.0.3 到 1.0.5。这意味着：</p><ul><li>看到本站和你机器上的行为不一致，<strong>先信你的机器</strong>，然后按 <code>grok version</code> 去对 <a href="https://x.ai/build/changelog" target="_blank" rel="noreferrer">changelog</a>。</li><li>changelog 可以比 <a href="https://docs.x.ai/build/cli/reference" target="_blank" rel="noreferrer">CLI Reference</a> 更早上新命令。文档里查不到的新行为，去 changelog 找。</li><li>上游仓库 <a href="https://github.com/xai-org/grok-build" target="_blank" rel="noreferrer">xai-org/grok-build</a> 是 Apache-2.0 开源的，但<strong>不接受外部 PR</strong>，反馈渠道是 TUI 里的 <code>/feedback</code>。所以不要指望社区 fork 能反哺主线，社区信息的权重要比官方低一档。</li></ul><p>判断一条信息还有效的最快手段是 <code>grok inspect</code>——它直接告诉你这台机器上实际加载了什么配置、规则、skill、plugin、hook 和 MCP server。文档讲的是应该怎样，<code>grok inspect</code> 讲的是实际怎样。</p><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./">Grok Build 学习地图</a></li><li><a href="./grok-cli.html">Grok Build 教程</a> — 从零跑起来</li><li><a href="./grok-cookbook.html">Grok Build 实战手册</a> — 具体任务怎么做</li><li><a href="./grok-cheatsheet.html">Grok Build 速查表</a> — 命令、配置键、环境变量</li><li><a href="./grok-chat.html">Grok 聊天</a></li><li><a href="./grok-imagine.html">Imagine</a></li><li><a href="./grok-voice.html">Voice</a></li><li><a href="./grok-connectors.html">Connectors</a></li><li><a href="./grok-bot.html">Grok Bot</a> — 云电脑同事</li><li><a href="./grok-business.html">Grok Business</a></li></ul>',69)])])}const b=o(a,[["render",l]]);export{m as __pageData,b as default};
